export const pageMarkup = "<div class=\"topbar\"><div class=\"container\"><span>☀ Clean energy. Smarter savings.</span><span>Serving Aruppukottai &amp; nearby areas · Tamil Nadu</span></div></div>\n<header class=\"nav\"><div class=\"container navin\">\n<a class=\"brand\" href=\"#home\" aria-label=\"VAANAM Solar Solutions home\"><img src=\"data:image/png;base64,\" alt=\"VAANAM Solar Solutions logo\"></a>\n<div class=\"lang-switch\" role=\"group\" aria-label=\"Choose language\"><button type=\"button\" class=\"lang-btn active\" data-lang=\"en\">EN</button><button type=\"button\" class=\"lang-btn\" data-lang=\"ta\">தமிழ்</button></div><nav class=\"navlinks\" aria-label=\"Main navigation\"><a href=\"#services\"><span data-en=\"Solutions\" data-ta=\"சேவைகள்\">Solutions</span></a><a href=\"#benefits\"><span data-en=\"Why Solar\" data-ta=\"சோலார் ஏன்?\">Why Solar</span></a><a href=\"#subsidy\"><span data-en=\"Subsidy\" data-ta=\"மானியம்\">Subsidy</span></a><a href=\"#projects\"><span data-en=\"Projects\" data-ta=\"திட்டங்கள்\">Projects</span></a><a href=\"#contact\"><span data-en=\"Contact\" data-ta=\"தொடர்பு\">Contact</span></a><a class=\"btn btn-primary\" href=\"#contact\"><span data-en=\"Get a Quote ↗\" data-ta=\"விலை விவரம் ↗\">Get a Quote ↗</span></a></nav>\n</div></header>\n<main>\n<section class=\"hero\" id=\"home\"><div class=\"container hero-grid\">\n<div><div class=\"eyebrow\">VAANAM Solar Solutions · Aruppukottai</div><h1><span data-en=\"Let the sun power your home.\" data-ta=\"சூரியன் உங்கள் வீட்டிற்கு மின்சாரம் தரட்டும்.\">Let the sun power your home.</span> <span data-en=\"Not your bills.\" data-ta=\"மின்கட்டணத்தை குறைக்க உதவட்டும்.\">Not your bills.</span></h1><p>Make the switch to clean, dependable solar energy with a solution designed around your roof, electricity usage and budget.</p><div class=\"hero-actions\"><a class=\"btn btn-primary\" href=\"#contact\"><span data-en=\"Get a Free Consultation\" data-ta=\"இலவச ஆலோசனை பெறுங்கள்\">Get a Free Consultation</span> <span>↗</span></a><a class=\"btn btn-outline\" href=\"https://wa.me/918428420505?text=Hi%20VAANAM%20Solar%20Solutions%2C%20I%20would%20like%20to%20know%20about%20rooftop%20solar.\" target=\"_blank\" rel=\"noopener\"><span data-en=\"☏ WhatsApp Us\" data-ta=\"☏ வாட்ஸ்அப் செய்யுங்கள்\">☏ WhatsApp Us</span></a></div><div class=\"hero-notes\"><span><i class=\"check\">✓</i> Solutions for homes &amp; businesses</span><span><i class=\"check\">✓</i> Consultation-led recommendations</span></div></div>\n<div class=\"hero-photo\"><img src=\"https://images.unsplash.com/photo-1509391366360-2e959784a276?auto=format&fit=crop&w=1100&q=90\" alt=\"Solar panels generating clean energy under the sun\"><div class=\"sun-icon\">☀</div><div class=\"photo-tag\"><strong>Make sunlight work for you.</strong><small>Explore a solar system suited to your needs.</small></div></div>\n</div></section>\n<div class=\"trustbar\"><div class=\"container trustgrid\">\n<div class=\"trustitem\"><div class=\"trusticon\">⌂</div><div><b>Home Solar</b><small>Rooftop solutions</small></div></div>\n<div class=\"trustitem\"><div class=\"trusticon\">▦</div><div><b>Business Solar</b><small>Commercial needs</small></div></div>\n<div class=\"trustitem\"><div class=\"trusticon\">↗</div><div><b>Bill Savings</b><small>Use solar energy</small></div></div>\n<div class=\"trustitem\"><div class=\"trusticon\">☏</div><div><b>Local Enquiries</b><small>Aruppukottai, TN</small></div></div>\n</div></div>\n<section class=\"section\" id=\"services\"><div class=\"container\"><div class=\"section-head\"><div class=\"kicker\">Our solar solutions</div><h2><span data-en=\"The right solar setup starts with the right advice.\" data-ta=\"சரியான ஆலோசனையிலிருந்து சரியான சோலார் அமைப்பு தொடங்குகிறது.\">The right solar setup starts with the right advice.</span></h2><p>Every property is different. Explore the main system types, then contact us to discuss what fits your needs.</p></div>\n<div class=\"services\">\n<article class=\"service\"><img src=\"https://images.unsplash.com/photo-1592833159155-c62df1b65634?auto=format&fit=crop&w=900&q=85\" alt=\"Solar panels on a home roof\"><div class=\"service-body\"><span class=\"service-num\">01 / RESIDENTIAL</span><h3 data-en=\"Home Rooftop Solar\" data-ta=\"வீட்டு மாடி சோலார்\">Home Rooftop Solar</h3><p data-en=\"Generate power at home, use more of the sunlight available to you and explore eligibility for applicable residential subsidy schemes.\" data-ta=\"வீட்டிலேயே சூரிய மின்சாரம் உற்பத்தி செய்து, மின்கட்டணத்தை குறைக்கும் வாய்ப்புகளை அறியுங்கள். பொருந்தக்கூடிய வீட்டு மானியத் தகுதியையும் சரிபார்க்கலாம்.\">Generate power at home, use more of the sunlight available to you and explore eligibility for applicable residential subsidy schemes.</p><a class=\"textlink\" href=\"#contact\"><span data-en=\"Discuss home solar\" data-ta=\"வீட்டு சோலார் பற்றி பேசுங்கள்\">Discuss home solar</span> <span>↗</span></a></div></article>\n<article class=\"service\"><img src=\"https://images.unsplash.com/photo-1497435334941-8c899ee9e8e9?auto=format&fit=crop&w=900&q=85\" alt=\"Large-scale solar panels\"><div class=\"service-body\"><span class=\"service-num\">02 / COMMERCIAL</span><h3 data-en=\"Commercial Solar\" data-ta=\"வணிக சோலார்\">Commercial Solar</h3><p data-en=\"Explore rooftop solar for shops, offices, warehouses and other businesses looking to manage daytime electricity consumption.\" data-ta=\"கடைகள், அலுவலகங்கள், கிடங்குகள் மற்றும் தொழில்களுக்கான மாடி சோலார் தீர்வுகளை அறியுங்கள்.\">Explore rooftop solar for shops, offices, warehouses and other businesses looking to manage daytime electricity consumption.</p><a class=\"textlink\" href=\"#contact\"><span data-en=\"Discuss business solar\" data-ta=\"வணிக சோலார் பற்றி பேசுங்கள்\">Discuss business solar</span> <span>↗</span></a></div></article>\n<article class=\"service\"><img src=\"https://images.unsplash.com/photo-1508514177221-188b1cf16e9d?auto=format&fit=crop&w=900&q=85\" alt=\"Solar energy equipment in sunlight\"><div class=\"service-body\"><span class=\"service-num\">03 / SYSTEM OPTIONS</span><h3 data-en=\"On-grid, Off-grid &amp; Hybrid\" data-ta=\"ஆன்-கிரிட், ஆஃப்-கிரிட் மற்றும் ஹைப்ரிட்\">On-grid, Off-grid &amp; Hybrid</h3><p>Understand grid-connected systems, battery backup options and hybrid setups before choosing equipment for your property.</p><a class=\"textlink\" href=\"#contact\">Find your system <span>↗</span></a></div></article>\n</div></div></section>\n<section class=\"section section-soft\" id=\"benefits\"><div class=\"container why-grid\"><div class=\"why-photo\"><img src=\"https://images.unsplash.com/photo-1508514177221-188b1cf16e9d?auto=format&fit=crop&w=1000&q=85\" alt=\"Rooftop solar panels in bright daylight\"><div class=\"why-stamp\"><b>Clean energy, long-term thinking.</b><small>Start with a site assessment and a clear quotation.</small></div></div>\n<div class=\"why-copy\"><div class=\"kicker\">Why consider solar?</div><h2><span data-en=\"A smarter way to power everyday life.\" data-ta=\"அன்றாட மின்சாரத்திற்கு புத்திசாலித்தனமான தீர்வு.\">A smarter way to power everyday life.</span></h2><p>Solar can help you make better use of your roof and reduce how much electricity you need to buy from the grid. Actual savings depend on system size, sunlight, usage and your tariff.</p><div class=\"benefits\">\n<div class=\"benefit\"><div class=\"benefit-icon\">✓</div><div><b>Potential bill savings</b><small>Match the system to your real consumption.</small></div></div>\n<div class=\"benefit\"><div class=\"benefit-icon\">⌂</div><div><b>Designed for your roof</b><small>Consider roof space, shade and orientation.</small></div></div>\n<div class=\"benefit\"><div class=\"benefit-icon\">☀</div><div><b>Cleaner electricity</b><small>Use a renewable source of energy.</small></div></div>\n<div class=\"benefit\"><div class=\"benefit-icon\">↗</div><div><b>Guided next steps</b><small>Ask about equipment, approvals and upkeep.</small></div></div>\n</div><div style=\"margin-top:28px\"><a class=\"btn btn-dark\" href=\"#contact\">Check solar for my property ↗</a></div></div></div></section>\n<section class=\"section subsidy\" id=\"subsidy\"><div class=\"container subsidy-grid\"><div><div class=\"kicker\" data-en=\"Government subsidy guide\" data-ta=\"அரசு மானிய வழிகாட்டி\">Government subsidy guide</div><h2 data-en=\"Know the support available before you invest.\" data-ta=\"முதலீடு செய்வதற்கு முன் கிடைக்கக்கூடிய மானியத்தை அறியுங்கள்.\">Know the support available before you invest.</h2><p data-en=\"For eligible domestic rooftop solar consumers in Tamil Nadu, the official state portal currently lists central assistance plus proposed state assistance. Benefits depend on eligibility, approved components, vendor empanelment and completion of the required process.\" data-ta=\"தமிழ்நாட்டில் தகுதியுள்ள வீட்டு மின்நுகர்வோருக்கு, மத்திய அரசின் உதவியுடன் மாநில அரசின் உதவியும் கிடைக்கலாம் என அதிகாரப்பூர்வ மாநில இணையதளம் குறிப்பிடுகிறது. தகுதி, அங்கீகரிக்கப்பட்ட உபகரணங்கள், அங்கீகரிக்கப்பட்ட நிறுவனம் மற்றும் நடைமுறைகள் பூர்த்தி செய்யப்படுதல் அவசியம்.\">For eligible domestic rooftop solar consumers in Tamil Nadu, the official state portal currently lists central assistance plus proposed state assistance. Benefits depend on eligibility, approved components, vendor empanelment and completion of the required process.</p><a class=\"btn btn-outline\" href=\"https://www.tnebltd.gov.in/usrp/\" target=\"_blank\" rel=\"noopener\" data-en=\"Open Tamil Nadu Solar Portal ↗\" data-ta=\"தமிழ்நாடு சோலார் இணையதளத்தைத் திறக்க ↗\">Open Tamil Nadu Solar Portal ↗</a></div>\n<div class=\"subsidy-card\"><span class=\"smallcap\" data-en=\"Residential rooftop solar · indicative subsidy\" data-ta=\"வீட்டு மாடி சோலார் · வழிகாட்டும் மானியத் தொகை\">Residential rooftop solar · indicative subsidy</span>\n<div class=\"subsidy-table-wrap\"><table class=\"subsidy-table\"><thead><tr><th data-en=\"System size\" data-ta=\"அமைப்பு திறன்\">System size</th><th data-en=\"Central\" data-ta=\"மத்திய அரசு\">Central</th><th data-en=\"TN state*\" data-ta=\"தமிழ்நாடு*\">TN state*</th><th data-en=\"Total*\" data-ta=\"மொத்தம்*\">Total*</th></tr></thead><tbody>\n<tr><td>1 kW</td><td>₹30,000</td><td>₹5,000</td><td><b>₹35,000</b></td></tr>\n<tr><td>2 kW</td><td>₹60,000</td><td>₹10,000</td><td><b>₹70,000</b></td></tr>\n<tr><td>3 kW</td><td>₹78,000</td><td>₹22,000</td><td><b>₹1,00,000</b></td></tr>\n<tr><td>Above 3 kW</td><td>₹78,000 max</td><td>₹22,000 max</td><td><b>₹1,00,000 max</b></td></tr>\n</tbody></table></div>\n<p class=\"disclaimer\" data-en=\"*Based on the Tamil Nadu state portal's published subsidy structure checked in October 2026. State assistance is subject to scheme conditions and disbursal sequence. Residential grid-connected systems, DCR-compliant/ALMM-listed modules and a TEDA-empanelled vendor may be required. Confirm current terms directly with the official portals; subsidy is not guaranteed.\" data-ta=\"*அக்டோபர் 2026-இல் தமிழ்நாடு மாநில இணையதளத்தில் வெளியிடப்பட்ட மானிய விவரங்களின் அடிப்படையில். மாநில மானியம் திட்ட விதிமுறைகள் மற்றும் பணம் வழங்கும் நடைமுறைகளுக்கு உட்பட்டது. வீட்டு மின்கட்டமைப்புடன் இணைக்கப்பட்ட அமைப்பு, DCR/ALMM விதிகளுக்கு இணங்கும் பேனல்கள் மற்றும் TEDA அங்கீகரித்த நிறுவனம் தேவைப்படலாம். தற்போதைய விதிகளை அதிகாரப்பூர்வ இணையதளங்களில் உறுதிப்படுத்தவும்; மானியம் உறுதியானது அல்ல.\">*Based on the Tamil Nadu state portal's published subsidy structure checked in October 2026. State assistance is subject to scheme conditions and disbursal sequence. Residential grid-connected systems, DCR-compliant/ALMM-listed modules and a TEDA-empanelled vendor may be required. Confirm current terms directly with the official portals; subsidy is not guaranteed.</p>\n<a class=\"btn btn-primary\" style=\"width:100%;margin-top:15px\" href=\"https://pmsuryaghar.gov.in/\" target=\"_blank\" rel=\"noopener\" data-en=\"Apply / check national portal ↗\" data-ta=\"தேசிய இணையதளத்தில் விண்ணப்பிக்க / சரிபார்க்க ↗\">Apply / check national portal ↗</a>\n<a class=\"textlink\" style=\"display:inline-block;margin-top:15px\" href=\"https://www.tnebltd.gov.in/usrp/faq.xhtml\" target=\"_blank\" rel=\"noopener\" data-en=\"Read official FAQs and process →\" data-ta=\"அதிகாரப்பூர்வ கேள்விகள் மற்றும் நடைமுறையைப் படிக்க →\">Read official FAQs and process →</a>\n</div></div></section>\n<section class=\"section\" id=\"process\"><div class=\"container\"><div class=\"section-head\"><div class=\"kicker\">Simple process</div><h2><span data-en=\"From first enquiry to solar-ready.\" data-ta=\"முதல் விசாரணையிலிருந்து சோலார் நிறுவல் வரை.\">From first enquiry to solar-ready.</span></h2><p>A clear process helps you understand the scope, cost and next steps before you commit.</p></div>\n<div class=\"steps\"><div class=\"step\"><div class=\"step-no\">01</div><h3>Tell us your needs</h3><p>Share your location, property type and recent electricity bill.</p></div><div class=\"step\"><div class=\"step-no\">02</div><h3>Assess the site</h3><p>Review roof space, shade, usage and suitable system capacity.</p></div><div class=\"step\"><div class=\"step-no\">03</div><h3>Review your quote</h3><p>Understand the proposed equipment, price, inclusions and terms.</p></div><div class=\"step\"><div class=\"step-no\">04</div><h3>Plan installation</h3><p>Confirm applicable approvals, installation schedule and after-sales support.</p></div></div></div></section>\n<section class=\"section section-soft\" id=\"projects\"><div class=\"container\"><div class=\"section-head\"><div class=\"kicker\">Solar inspiration</div><h2>See what solar can look like.</h2><p>Use this gallery as a design preview. Replace these sample images with VAANAM's real installation photos before publishing.</p></div>\n<div class=\"gallery\"><img src=\"https://images.unsplash.com/photo-1509391366360-2e959784a276?auto=format&fit=crop&w=1000&q=85\" alt=\"Sample rooftop solar installation\"><img src=\"https://images.unsplash.com/photo-1497435334941-8c899ee9e8e9?auto=format&fit=crop&w=800&q=85\" alt=\"Sample solar panel array\"><img src=\"https://images.unsplash.com/photo-1508514177221-188b1cf16e9d?auto=format&fit=crop&w=800&q=85\" alt=\"Sample solar modules\"><img src=\"https://images.unsplash.com/photo-1592833159155-c62df1b65634?auto=format&fit=crop&w=1000&q=85\" alt=\"Sample solar panels on a building\"></div><p class=\"gallery-note\">Sample imagery only — not represented as completed VAANAM projects.</p></div></section>\n<section class=\"section green-section\" id=\"green-living\"><div class=\"container green-grid\"><div class=\"green-copy\"><div class=\"kicker\" data-en=\"Power the future. Keep it green.\" data-ta=\"எதிர்காலத்திற்கு மின்சாரம் · பசுமையைப் பாதுகாப்போம்.\">Power the future. Keep it green.</div><h2 data-en=\"Clean energy belongs in a greener home.\" data-ta=\"பசுமையான வீட்டிற்கு தூய்மையான சூரிய மின்சாரம்.\">Clean energy belongs in a greener home.</h2><p data-en=\"Pair smart energy choices with greener surroundings. Solar panels generate electricity from sunlight, while native plants and shade trees can make outdoor spaces more inviting. Plan tree placement so branches and shade do not block your solar panels.\" data-ta=\"சூரிய ஒளியிலிருந்து மின்சாரம் உருவாக்கும் சோலார் அமைப்புடன், உள்ளூர் தாவரங்கள் மற்றும் நிழல் தரும் மரங்களையும் இணைத்து பசுமையான சூழலை உருவாக்குங்கள். சோலார் பேனல்களுக்கு நிழல் விழாதபடி மரங்கள் மற்றும் கிளைகளின் இடத்தைத் திட்டமிடுங்கள்.\">Pair smart energy choices with greener surroundings. Solar panels generate electricity from sunlight, while native plants and shade trees can make outdoor spaces more inviting. Plan tree placement so branches and shade do not block your solar panels.</p><div class=\"green-points\"><span>🌱 <b data-en=\"Greener spaces\" data-ta=\"பசுமையான சூழல்\">Greener spaces</b></span><span>☀️ <b data-en=\"Renewable energy\" data-ta=\"புதுப்பிக்கத்தக்க ஆற்றல்\">Renewable energy</b></span><span>💧 <b data-en=\"Mindful water use\" data-ta=\"நீர் சிக்கனம்\">Mindful water use</b></span></div><a class=\"btn btn-dark\" href=\"#contact\" data-en=\"Plan my solar setup ↗\" data-ta=\"எனது சோலார் அமைப்பைத் திட்டமிட ↗\">Plan my solar setup ↗</a></div><div class=\"green-images\"><img src=\"https://images.unsplash.com/photo-1416879595457-9f7f9e5c2c2d?auto=format&fit=crop&w=900&q=85\" alt=\"Green plants growing in a sunlit garden\"><img src=\"https://images.unsplash.com/photo-1497250681960-ef046c08a56e?auto=format&fit=crop&w=700&q=85\" alt=\"Lush green houseplants\"><div class=\"green-note\"><b data-en=\"A brighter, greener tomorrow\" data-ta=\"ஒளிமயமான பசுமையான நாளை\">A brighter, greener tomorrow</b><small data-en=\"Solar + thoughtful greenery\" data-ta=\"சோலார் + கவனமான பசுமை\">Solar + thoughtful greenery</small></div></div></div></section><section class=\"section\" id=\"faq\"><div class=\"container\"><div class=\"section-head\"><div class=\"kicker\">Questions, answered</div><h2><span data-en=\"Things to know before going solar.\" data-ta=\"சோலார் அமைப்பதற்கு முன் தெரிந்துகொள்ள வேண்டியவை.\">Things to know before going solar.</span></h2></div><div class=\"faq\">\n<details><summary>How do I know what system size I need?</summary><p>Start with your recent electricity bills and daytime usage. Roof area, shading, sanctioned load and your utility's requirements also affect the suitable size. A site assessment can help determine a realistic recommendation.</p></details>\n<details><summary>Can I get a government subsidy?</summary><p>Some residential rooftop systems may qualify under current government schemes. Check the official Tamil Nadu rooftop solar portal for the latest eligibility, application steps and vendor requirements before relying on a subsidy amount.</p></details>\n<details><summary>What is the difference between on-grid, off-grid and hybrid?</summary><p>On-grid systems work alongside the electricity grid; off-grid systems rely on local generation and storage; hybrid systems combine grid connection with battery capability. Backup behavior depends on the design and equipment.</p></details>\n<details><summary>How much can I save on my electricity bill?</summary><p>Savings depend on your monthly consumption, tariff, system size, solar generation, self-consumption and applicable net-metering rules. Ask for an estimate based on your bill rather than relying on a universal percentage.</p></details>\n<details><summary>What should be included in a quotation?</summary><p>Ask for panel and inverter make/model, system capacity, mounting structure, wiring and protection equipment, installation, approvals, net-metering scope, warranties, payment milestones and after-sales terms.</p></details>\n</div></div></section>\n<section class=\"section contact\" id=\"contact\"><div class=\"container contact-grid\"><div class=\"contact-copy\"><div class=\"kicker\">Let's talk solar</div><h2><span data-en=\"Your solar journey starts with one conversation.\" data-ta=\"உங்கள் சோலார் பயணம் ஒரு உரையாடலிலிருந்து தொடங்குகிறது.\">Your solar journey starts with one conversation.</span></h2><p>Tell us a little about your property and electricity usage. We'll help you identify the right questions and next steps.</p>\n<div class=\"contact-row\"><div class=\"contact-icon\">⌖</div><div><b>Visit our location</b><small>2-18-4/2, Postal Colony,<br>Near Union Office, Aruppukottai – 626101,<br>Tamil Nadu, India</small></div></div>\n<div class=\"contact-row\"><div class=\"contact-icon\">☎</div><div><b>Call / WhatsApp</b><small><a href=\"tel:+918428420505\">84284 20505</a><br><a href=\"tel:+918668051108\">86680 51108 · Balaji</a></small></div></div>\n<a class=\"map-link\" href=\"https://www.google.com/maps/search/?api=1&query=2-18-4%2F2%2C+Postal+Colony%2C+Near+Union+Office%2C+Aruppukottai+626101\" target=\"_blank\" rel=\"noopener\">Get directions on Google Maps ↗</a>\n</div>\n<form class=\"form-card\" id=\"quoteForm\"><h3><span data-en=\"Request a solar consultation\" data-ta=\"சோலார் ஆலோசனை கோருங்கள்\">Request a solar consultation</span></h3><p>Fill in the details below. The form opens WhatsApp with your enquiry ready to send.</p><div class=\"form-grid\">\n<div class=\"field\"><label for=\"name\">Your name *</label><input id=\"name\" name=\"name\" required placeholder=\"Enter your name\"></div>\n<div class=\"field\"><label for=\"phone\">Phone number *</label><input id=\"phone\" name=\"phone\" required inputmode=\"tel\" pattern=\"[0-9+() -]{8,}\" placeholder=\"Your contact number\"></div>\n<div class=\"field\"><label for=\"property\">Property type</label><select id=\"property\" name=\"property\"><option>House / Residential</option><option>Shop / Office</option><option>Factory / Industrial</option><option>Other</option></select></div>\n<div class=\"field\"><label for=\"bill\">Monthly electricity bill</label><select id=\"bill\" name=\"bill\"><option>Not sure</option><option>Below ₹1,500</option><option>₹1,500 – ₹3,000</option><option>₹3,000 – ₹6,000</option><option>Above ₹6,000</option></select></div>\n<div class=\"field full\"><label for=\"location\">Your area / town</label><input id=\"location\" name=\"location\" placeholder=\"e.g. Aruppukottai\"></div>\n<div class=\"field full\"><label for=\"message\">Anything else you'd like us to know?</label><textarea id=\"message\" name=\"message\" placeholder=\"Roof type, backup needs, questions...\"></textarea></div>\n</div><button class=\"btn btn-primary\" type=\"submit\"><span data-en=\"Send enquiry on WhatsApp ↗\" data-ta=\"வாட்ஸ்அப்பில் விசாரணை அனுப்ப ↗\">Send enquiry on WhatsApp ↗</span></button><div class=\"form-note\">Your details will be passed to WhatsApp when you press the button.</div></form></div></section>\n</main>\n<footer class=\"footer\"><div class=\"container\"><div class=\"footer-top\"><div><img src=\"data:image/png;base64,\" alt=\"VAANAM Solar Solutions\"><p>Helping homes and businesses explore practical solar energy solutions in Aruppukottai and nearby areas.</p></div><div class=\"footer-links\"><a href=\"#services\"><span data-en=\"Solutions\" data-ta=\"சேவைகள்\">Solutions</span></a><a href=\"#benefits\"><span data-en=\"Why Solar\" data-ta=\"சோலார் ஏன்?\">Why Solar</span></a><a href=\"#subsidy\"><span data-en=\"Subsidy\" data-ta=\"மானியம்\">Subsidy</span></a><a href=\"#projects\">Gallery</a><a href=\"#contact\"><span data-en=\"Contact\" data-ta=\"தொடர்பு\">Contact</span></a></div></div><div class=\"copyright\"><span>© <span id=\"year\"></span> VAANAM Solar Solutions. All rights reserved.</span><span>Solar information is indicative; confirm system design, pricing and eligibility directly.</span></div></div></footer>\n<a class=\"whatsapp-float\" href=\"https://wa.me/918428420505?text=Hi%20VAANAM%20Solar%20Solutions%2C%20I%20would%20like%20a%20solar%20consultation.\" target=\"_blank\" rel=\"noopener\" aria-label=\"Chat with VAANAM on WhatsApp\"><svg viewBox=\"0 0 32 32\" aria-hidden=\"true\"><path d=\"M16 .5A15.4 15.4 0 0 0 2.8 24L1 31l7.2-1.9A15.5 15.5 0 1 0 16 .5zm0 28.2a12.7 12.7 0 0 1-6.5-1.8l-.5-.3-4.3 1.1 1.1-4.2-.3-.5A12.8 12.8 0 1 1 16 28.7zm7-9.5c-.4-.2-2.1-1-2.4-1.1-.3-.1-.6-.2-.8.2-.3.4-.9 1.1-1.1 1.3-.2.3-.4.3-.8.1-.4-.2-1.5-.6-2.8-1.8-1-.9-1.7-2-1.9-2.3-.2-.4 0-.6.2-.8l.6-.7c.2-.2.3-.4.4-.6.1-.3 0-.5 0-.7-.1-.2-.8-2-1.1-2.7-.3-.7-.6-.6-.8-.6h-.7c-.3 0-.7.1-1 .5-.4.4-1.3 1.3-1.3 3.1s1.3 3.6 1.5 3.9c.2.3 2.6 4 6.3 5.6.9.4 1.6.6 2.1.7.9.3 1.7.2 2.3.1.7-.1 2.1-.9 2.4-1.8.3-.9.3-1.6.2-1.8-.1-.2-.3-.3-.7-.5z\"/></svg><span>WhatsApp us</span></a>\n<div class=\"mobile-cta\"><a class=\"btn btn-dark\" href=\"tel:+918428420505\">☎ Call Now</a><a class=\"btn btn-primary\" href=\"#contact\">Get Free Quote ↗</a></div>\n<script>\ndocument.getElementById('year').textContent = new Date().getFullYear();\ndocument.getElementById('quoteForm').addEventListener('submit', function(e){\n e.preventDefault();\n const d = new FormData(this);\n const msg = `Hi VAANAM Solar Solutions, I'd like a solar consultation.%0A%0AName: ${encodeURIComponent(d.get('name'))}%0APhone: ${encodeURIComponent(d.get('phone'))}%0AProperty: ${encodeURIComponent(d.get('property'))}%0AMonthly bill: ${encodeURIComponent(d.get('bill'))}%0AArea: ${encodeURIComponent(d.get('location') || 'Not provided')}%0AMessage: ${encodeURIComponent(d.get('message') || 'Not provided')}`;\n window.open('https://wa.me/918428420505?text=' + msg, '_blank', 'noopener');\n});\n</script>\n\n<script>\n(function(){\n const translations = {\n  en: {},\n  ta: {\n   \"Home Rooftop Solar\":\"வீட்டு மாடி சோலார்\",\"Commercial Solar\":\"வணிக சோலார்\",\n   \"On-grid, Off-grid & Hybrid\":\"ஆன்-கிரிட், ஆஃப்-கிரிட் மற்றும் ஹைப்ரிட்\",\n   \"Solar inspiration\":\"சோலார் வடிவமைப்பு உதாரணங்கள்\",\"See what solar can look like.\":\"சோலார் அமைப்பு எப்படி இருக்கும் என்று பாருங்கள்.\",\n   \"Use this gallery as a design preview. Replace these sample images with VAANAM's real installation photos before publishing.\":\"இவை வடிவமைப்பு மாதிரி படங்கள். வெளியிடுவதற்கு முன் VAANAM நிறுவிய உண்மையான படங்களால் மாற்றவும்.\",\n   \"Our solar solutions\":\"எங்கள் சோலார் தீர்வுகள்\",\"Why consider solar?\":\"சோலாரை ஏன் தேர்வு செய்ய வேண்டும்?\",\n   \"Solar can help you make better use of your roof and reduce how much electricity you need to buy from the grid. Actual savings depend on system size, sunlight, usage and your tariff.\":\"சோலார் உங்கள் கூரையை சிறப்பாகப் பயன்படுத்தவும், மின்வாரியத்திலிருந்து வாங்கும் மின்சாரத்தை குறைக்கவும் உதவும். உண்மையான சேமிப்பு அமைப்பு திறன், சூரிய ஒளி, பயன்பாடு மற்றும் மின்கட்டணத்தைப் பொறுத்தது.\",\n   \"Home Solar\":\"வீட்டு சோலார்\",\"Business Solar\":\"வணிக சோலார்\",\"Bill Savings\":\"மின்கட்டண சேமிப்பு\",\"Local Enquiries\":\"உள்ளூர் விசாரணைகள்\",\n   \"Rooftop solutions\":\"மாடி சோலார் தீர்வுகள்\",\"Commercial needs\":\"வணிகத் தேவைகள்\",\"Use solar energy\":\"சூரிய மின்சாரத்தைப் பயன்படுத்துங்கள்\",\"Aruppukottai, TN\":\"அருப்புக்கோட்டை, தமிழ்நாடு\",\n   \"Tell us your needs\":\"உங்கள் தேவைகளைச் சொல்லுங்கள்\",\"Assess the site\":\"இடத்தை மதிப்பீடு செய்யுங்கள்\",\"Review your quote\":\"விலைப்பட்டியலைப் பாருங்கள்\",\"Plan installation\":\"நிறுவலைத் திட்டமிடுங்கள்\",\n   \"Share your location, property type and recent electricity bill.\":\"உங்கள் பகுதி, சொத்து வகை மற்றும் சமீபத்திய மின்கட்டண விவரத்தைப் பகிருங்கள்.\",\n   \"Review roof space, shade, usage and suitable system capacity.\":\"கூரை இடம், நிழல், மின்பயன்பாடு மற்றும் பொருத்தமான திறனை மதிப்பிடுங்கள்.\",\n   \"Understand the proposed equipment, price, inclusions and terms.\":\"பரிந்துரைக்கப்பட்ட உபகரணங்கள், விலை மற்றும் விதிமுறைகளைப் புரிந்துகொள்ளுங்கள்.\",\n   \"Confirm applicable approvals, installation schedule and after-sales support.\":\"தேவையான அனுமதிகள், நிறுவல் அட்டவணை மற்றும் விற்பனைக்குப் பிந்தைய சேவையை உறுதிசெய்யுங்கள்.\",\n   \"Your name *\":\"உங்கள் பெயர் *\",\"Phone number *\":\"தொலைபேசி எண் *\",\"Property type\":\"சொத்து வகை\",\"Monthly electricity bill\":\"மாத மின்கட்டணம்\",\"Your area / town\":\"உங்கள் பகுதி / நகரம்\",\n   \"House / Residential\":\"வீடு / குடியிருப்பு\",\"Shop / Office\":\"கடை / அலுவலகம்\",\"Factory / Industrial\":\"தொழிற்சாலை / தொழில்\",\"Other\":\"மற்றவை\",\"Not sure\":\"தெரியவில்லை\",\n   \"Below ₹1,500\":\"₹1,500-க்கு கீழ்\",\"₹1,500 – ₹3,000\":\"₹1,500 – ₹3,000\",\"₹3,000 – ₹6,000\":\"₹3,000 – ₹6,000\",\"Above ₹6,000\":\"₹6,000-க்கு மேல்\",\n   \"Anything else you'd like us to know?\":\"வேறு ஏதேனும் தெரிவிக்க விரும்புகிறீர்களா?\",\"Enter your name\":\"உங்கள் பெயரை உள்ளிடுங்கள்\",\"Your contact number\":\"உங்கள் தொலைபேசி எண்\",\"e.g. Aruppukottai\":\"உதா. அருப்புக்கோட்டை\",\n   \"From first enquiry to solar-ready.\":\"முதல் விசாரணையிலிருந்து சோலார் நிறுவல் வரை.\"\n  }\n };\n function setLanguage(lang){\n  document.documentElement.lang = lang === 'ta' ? 'ta' : 'en';\n  document.querySelectorAll('[data-en][data-ta]').forEach(el => {\n    el.textContent = lang === 'ta' ? el.getAttribute('data-ta') : el.getAttribute('data-en');\n  });\n  document.querySelectorAll('.lang-btn').forEach(b => b.classList.toggle('active', b.dataset.lang === lang));\n  document.querySelectorAll('h1,h2,h3,p,summary,a,button,label,small,b').forEach(el => {\n    if(el.children.length === 0 && !el.hasAttribute('data-en')){\n      const original = el.dataset.originalText || el.textContent.trim();\n      if(!el.dataset.originalText) el.dataset.originalText = original;\n      const translated = translations.ta[original];\n      if(lang === 'ta' && translated) el.textContent = translated;\n      else if(lang === 'en') el.textContent = el.dataset.originalText;\n    }\n  });\n  try{localStorage.setItem('vaanam-lang',lang)}catch(e){}\n }\n document.querySelectorAll('.lang-btn').forEach(b=>b.addEventListener('click',()=>setLanguage(b.dataset.lang)));\n let initial='en'; try{initial=localStorage.getItem('vaanam-lang')||'en'}catch(e){}\n setLanguage(initial);\n})();\n</script>";
